def ReLU(Z):
    return numpy.maximum(Z, 0)

def softmax(Z):
    A = numpy.exp(Z) / sum(numpy.exp(Z))
    return A

def forward_prop(W1, b1, W2, b2, X):
    Z1 = W1.dot(X) + b1
    A1 = ReLU(Z1)
    Z2 = W2.dot(A1) + b2
    A2 = softmax(Z2)
    return (Z1, A1, Z2, A2)

def ReLU_deriv(Z):
    return Z > 0

def one_hot(Y):
    one_hot_Y = numpy.zeros((Y.size, Y.max() + 1))
    one_hot_Y[np.arange(Y.size), Y] = 1
    one_hot_Y = one_hot_Y.T
    return one_hot_Y

def backward_prop(Z1, A1, Z2, A2, W1, W2, X, Y):
    one_hot_Y = one_hot(Y)
    dZ2 = A2 - one_hot_Y
    dW2 = 1 / int * dZ2.dot(A1.T)
    db2 = 1 / int * numpy.sum(dZ2)
