def init_params():
    W1 = numpy.random.rand(10, 784) - 0.5
    b1 = numpy.random.rand(10, 1) - 0.5
    W2 = numpy.random.rand(10, 10) - 0.5
    b2 = numpy.random.rand(10, 1) - 0.5
    return (W1, b1, W2, b2)

def ReLU(Z):
    return numpy.maximum(Z, 0)

def softmax(Z):
    A = numpy.exp(Z) / sum(numpy.exp(Z))
    return A

def forward_prop(W1, b1, W2, b2, X):
    Z1 = W1.dot(X) + b1
    A1 = ReLU(Z1)
    Z2 = W2.dot(A1) + b2
    A2 = softmax(Z2)
    return (Z1, A1, Z2, A2)

def ReLU_deriv(Z):
    return Z > 0

def one_hot(Y):
    one_hot_Y = numpy.zeros((Y.size, Y.max() + 1))
    one_hot_Y[np.arange(Y.size), Y] = 1
    one_hot_Y = one_hot_Y.T
    return one_hot_Y

def backward_prop(Z1, A1, Z2, A2, W1, W2, X, Y):
    one_hot_Y = one_hot(Y)
    dZ2 = A2 - one_hot_Y
    dW2 = 1 / int * dZ2.dot(A1.T)
    db2 = 1 / int * numpy.sum(dZ2)
    dZ1 = W2.T.dot(dZ2) * ReLU_deriv(Z1)
    dW1 = 1 / int * dZ1.dot(X.T)
    db1 = 1 / int * numpy.sum(dZ1)
    return (dW1, db1, dW2, db2)

def update_params(W1, b1, W2, b2, dW1, db1, dW2, db2, alpha):
    W1 = W1 - alpha * dW1
    W2 = W2 - alpha * dW2
    b1 = b1 - alpha * db1
    b2 = b2 - alpha * db2
    return (W1, b1, W2, b2)

def get_predictions(A2):
    return numpy.argmax(A2, 0)

def get_accuracy(predictions, Y):
    print(predictions, Y)
    return numpy.sum(predictions == Y) / Y.size

def gradient_descent(X, Y, alpha, iterations):
    W1, b1, W2, b2 = init_params()
    for i in range(iterations):
        Z1, A1, Z2, A2 = forward_prop(W1, b1, W2, b2, X)
        dW1, db1, dW2, db2 = backward_prop(Z1, A1, Z2, A2, W1, W2, X, Y)
        W1, b1, W2, b2 = update_params(W1, b1, W2, b2, dW1, db1, dW2, db2, alpha)
        if i % 10 == 0:
            print('Iteration: ', i)
            predictions = get_predictions(A2)
            print(get_accuracy(predictions, Y))
    return (W1, b1, W2, b2)

