def load_data(x_path, y_path, batch_size=64, dataset_size=28000, train=True):
    AUTOTUNE = tensorflow.data.AUTOTUNE
    train_size = int(0.8 * dataset_size)
    ds_x = tensorflow.data.TextLineDataset(x_path).skip(1)
    ds_y = tensorflow.data.TextLineDataset(y_path).skip(1).map(lambda y: tensorflow.strings.to_number(y, tensorflow.int32), num_parallel_calls=AUTOTUNE).map(lambda y: tensorflow.one_hot(y, 10))

    def sparse_x(line):
        fields = tensorflow.strings.split(line, ',')
        fields = tensorflow.strings.to_number(fields, tensorflow.float32)
        fields = fields / 255.0
        fields = tensorflow.reshape(fields, [28, 28])
        return fields
    ds_x = ds_x.map(sparse_x, num_parallel_calls=AUTOTUNE)
    ds = tensorflow.data.Dataset.zip((ds_x, ds_y))
    ds = ds.shuffle(dataset_size).batch(batch_size)
    if train:
        ds_train = ds.take(train_size // batch_size).prefetch(1)
        ds_val = ds.skip(train_size // batch_size).prefetch(1)
        return (ds_train, ds_val)
    else:
        return ds_x.batch(batch_size).prefetch(1)

